import { Pipe, PipeTransform } from '@angular/core';

@Pipe({
    name: 'weight',
    standalone: true
})
export class WeightPipe implements PipeTransform {

    transform(value: any): String | null {
        // if (value < 999) {
        //     return value + ' g'
        // } else {
        //     return (value / 1000) + ' kg';
        // }
        return `${parseFloat(value)} kg`
    }

}
